window.createQuizAdmin=async function(){
  modal('Create assessment',quizForm(),async e=>{
    try{
      const r=await api('/api/admin/quizzes',{method:'POST',body:JSON.stringify(normalizeForm(e.currentTarget))});
      closeModal();toast('Assessment created.');await window.editQuiz(r.id)
    }catch(err){toast(err.message)}
  })
};
window.addQuestion=async function(qid){
  function makeChoices(type){
    if(type==='short_answer')return '<div class="callout">Short-answer questions do not need answer choices.</div>';
    const kind=type==='multiple'?'checkbox':'radio';
    const vals=type==='boolean'?['True','False']:['','','',''];
    return '<div class="callout">Add the answer choices now. Mark the correct answer'+(type==='multiple'?'s':'')+'.</div>'+
      vals.map((v,i)=>'<div class="answer-editor-row"><input class="input" name="optionText[]" value="'+esc(v)+'" placeholder="Answer choice '+(i+1)+'"><label class="option answer-correct"><input type="'+kind+'" name="correct" value="'+i+'"><span>Correct</span></label></div>').join('')
  }
  const html=
    '<form id="modal-form" class="form-grid">'+
      '<div class="wide"><div class="field"><label>Question</label><textarea class="textarea" name="questionText" required></textarea></div></div>'+
      '<div><div class="field"><label>Type</label><select class="select" name="questionType" id="new-question-type"><option value="single">Multiple choice</option><option value="multiple">Multiple select</option><option value="boolean">True / false</option><option value="short_answer">Short answer</option></select></div></div>'+
      '<div><div class="field"><label>Points</label><input class="input" name="points" type="number" min="1" value="1"></div></div>'+
      '<div><div class="field"><label>Position</label><input class="input" name="position" type="number" min="1" value="1"></div></div>'+
      '<div class="wide" id="choice-editor">'+makeChoices('single')+'</div>'+
      '<div class="wide inline-actions"><button class="btn btn-quiet" type="button" onclick="closeModal()">Cancel</button><button class="btn btn-primary">Create question</button></div>'+
    '</form>';
  modal('Add question',html,async e=>{
    try{
      const form=e.currentTarget,type=form.querySelector('[name=questionType]').value;
      const texts=[...form.querySelectorAll('[name="optionText[]"]')].map(x=>x.value.trim()).filter(Boolean);
      const correct=[...form.querySelectorAll('[name=correct]:checked')].map(x=>Number(x.value));
      if(type!=='short_answer'){
        if(texts.length<2)return toast('Add at least two answer choices.');
        if(!correct.length)return toast('Mark at least one correct answer.');
        if(type!=='multiple'&&correct.length>1)return toast('Select one correct answer for this question.')
      }
      const r=await api('/api/admin/questions/new',{method:'POST',body:JSON.stringify({...normalizeForm(form),quizId:qid})});
      for(const [i,text] of texts.entries())await api('/api/admin/options/new',{method:'POST',body:JSON.stringify({questionId:r.id,optionText:text,isCorrect:correct.includes(i),position:i+1})});
      closeModal();toast('Question and answer choices added.');await window.editQuiz(qid)
    }catch(err){toast(err.message)}
  });
  document.querySelector('#new-question-type').onchange=e=>{document.querySelector('#choice-editor').innerHTML=makeChoices(e.target.value)}
};
window.addOption=async function(qid){
  try{
    const q=await findQuizByQuestion(qid);
    const type=q.question_type,kind=type==='multiple'?'checkbox':'radio',vals=type==='boolean'?['True','False']:['','','',''];
    const html='<form id="modal-form"><div class="callout">Add answer choices to <b>'+esc(q.question_text)+'</b>.</div><div id="extra-choice-list">'+
      vals.map((v,i)=>'<div class="answer-editor-row"><input class="input" name="optionText[]" value="'+esc(v)+'" placeholder="Answer choice '+(i+1)+'"><label class="option answer-correct"><input type="'+kind+'" name="correct" value="'+i+'"><span>Correct</span></label></div>').join('')+
      '<div class="inline-actions" style="margin-top:14px"><button class="btn btn-quiet" type="button" onclick="closeModal()">Cancel</button><button class="btn btn-primary">Add choices</button></div></form>';
    modal('Add answer choices',html,async e=>{
      try{
        const form=e.currentTarget,texts=[...form.querySelectorAll('[name="optionText[]"]')].map(x=>x.value.trim()),correct=[...form.querySelectorAll('[name=correct]:checked')].map(x=>Number(x.value));
        let added=0;
        for(const [i,text] of texts.entries()){if(!text)continue;await api('/api/admin/options/new',{method:'POST',body:JSON.stringify({questionId:qid,optionText:text,isCorrect:correct.includes(i),position:i+1})});added++}
        if(!added)return toast('Enter at least one answer choice.');
        closeModal();toast(added+' answer choice'+(added===1?'':'s')+' added.');await window.editQuiz(q.quiz_id)
      }catch(err){toast(err.message)}
    })
  }catch(err){toast(err.message)}
};

window.addEventListener('popstate',boot);
async function boot(){try{await loadMe();const screen=new URLSearchParams(location.search).get('screen')||'home';if(!ME&&screen!=='login')return nav('login');if(screen==='login')return ME?nav('home'):loginView();if(screen==='home')return home();if(screen==='learning')return learning();if(screen==='course')return course(new URLSearchParams(location.search).get('slug'));if(screen==='lesson')return lesson(new URLSearchParams(location.search).get('id'));if(screen==='certificates')return certificates();if(screen==='account')return account();if(screen==='admin')return admin();return home()}catch(e){app.innerHTML=`<div class="login"><div class="login-card"><h1>IRIS LUMERA</h1><p>${esc(e.message)}</p><button class="btn btn-primary" onclick="nav('home')">Return home</button></div></div>`}}
boot();
